mapper.select:
SELECT c.id, c.is_in_progress, c.name, c.number_of_learner, c.start_date, c.end_date, c.total_hours, c.total_days, c.daily_hours, c.break_time, c.lesson_start_time, c.lesson_end_time, c.lunch_start_time, c.lunch_end_time, c.created_at, c.updated_at, c.deleted_at, cra.classroom_id, cr.name AS classroom_name, MAX(CASE WHEN sd.position = 'COURSE_HEAD' THEN sa.user_id END) AS course_head_id, MAX(CASE WHEN sd.position = 'COURSE_HEAD' THEN u.fullname END) AS course_head_fullname, MAX(CASE WHEN sd.position = 'FULLTIME_INSTRUCTOR' THEN sa.user_id END) AS fulltime_instructor_id, MAX(CASE WHEN sd.position = 'FULLTIME_INSTRUCTOR' THEN u.fullname END) AS fulltime_instructor_fullname FROM course c
INNER JOIN learner_enrollment le ON c.id = le.course_id
LEFT JOIN staff_assignment sa ON c.id = sa.course_id LEFT JOIN staff_detail sd ON sa.user_id = sd.user_id LEFT JOIN user u ON sd.user_id = u.id LEFT JOIN classroom_allocation cra ON c.id = cra.course_id LEFT JOIN classroom cr ON cra.classroom_id = cr.id
le.user_id = #{loginUserId}
AND ( EXISTS ( SELECT 1 FROM staff_detail WHERE user_id = #{loginUserId} AND position = 'GENERAL_MANAGER' ) OR c.id IN ( SELECT course_id FROM staff_assignment WHERE user_id = #{loginUserId} ) )
AND c.${pageCourseReqDTO.type} like concat('%', #{pageCourseReqDTO.keyword}, '%')
AND c.is_in_progress = #{isInProgress}
AND c.id = #{courseId}
GROUP BY c.id ORDER BY ${pageCourseReqDTO.orderBy} ${pageCourseReqDTO.orderDirection}
LIMIT #{pageCourseReqDTO.offset}, #{pageCourseReqDTO.pageSize}

SELECT u.id, u.type, u.fullname, u.mobile, le.completion_status FROM user u LEFT JOIN learner_enrollment le ON u.id = le.user_id WHERE type = 'LEARNER' AND u.id NOT IN ( SELECT u.id FROM user u LEFT JOIN learner_enrollment le ON u.id = le.user_id WHERE le.completion_status = 'IN_PROGRESS')
AND ${pageUserReqDTO.type} like concat('%', #{pageUserReqDTO.keyword}, '%')
AND le.completion_status IS NULL
ORDER BY ${pageUserReqDTO.orderBy} ${pageUserReqDTO.orderDirection}
LIMIT #{pageUserReqDTO.offset}, #{pageUserReqDTO.pageSize}

